(function(){function boot(){const central=document.querySelector('#cadastros');if(central)central.remove();const nav=[...document.querySelectorAll('.nav')].find(x=>x.textContent.includes('Cadastros'));if(nav)nav.remove();document.querySelectorAll('.exclusive-agent-view').forEach(v=>{const h=v.querySelector('.head'),list=v.querySelector('.queue');if(!h||!list||h.querySelector('.env-add'))return;const key=v.id.replace('exclusive-',''),map={marketMaker:'marketMakers',site:'sites',nicho:'nichos',produto:'produtos'},dataKey=map[key];const add=document.createElement('button');add.className='btn primary env-add';add.textContent='+ Adicionar';h.appendChild(add);function render(){list.querySelectorAll('article').forEach((c,i)=>{const actions=document.createElement('div');actions.style='display:flex;gap:8px;margin-top:12px';actions.innerHTML='<button class="btn env-edit" data-i="'+i+'">Editar</button><button class="btn env-remove" data-i="'+i+'">Remover</button>';c.appendChild(actions)})}add.onclick=()=>{const value=prompt('Novo '+key+':');if(!value)return;const store=JSON.parse(localStorage.getItem('traficcagent-core-cadastros')||'{}');store[dataKey]=store[dataKey]||[];store[dataKey].push(value.trim());localStorage.setItem('traficcagent-core-cadastros',JSON.stringify(store));alert('Cadastro salvo. Atualize o ambiente para visualizar.');};list.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const store=JSON.parse(localStorage.getItem('traficcagent-core-cadastros')||'{}'),items=store[dataKey]||[];const i=+b.dataset.i;if(b.classList.contains('env-edit')){const value=prompt('Alterar cadastro:',items[i]);if(value){items[i]=value.trim();store[dataKey]=items;localStorage.setItem('traficcagent-core-cadastros',JSON.stringify(store));alert('Cadastro alterado. Atualize o ambiente.')}}if(b.classList.contains('env-remove')&&confirm('Remover este cadastro?')){items.splice(i,1);store[dataKey]=items;localStorage.setItem('traficcagent-core-cadastros',JSON.stringify(store));alert('Cadastro removido. Atualize o ambiente.')}});render()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else setTimeout(boot,60)})();
